-- app.Attendance (PostgreSQL / init-pilot conventions)
-- One row per person per day. Check-in and check-out each keep their own channel, photo, and GPS point.

CREATE SCHEMA IF NOT EXISTS app;

CREATE TABLE app."Attendance"
(
    "AttendanceId"              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "AttendanceGuid"            UUID NOT NULL DEFAULT gen_random_uuid(),
    "CompanyId"                 BIGINT NOT NULL,
    "CompanyOfficeId"           BIGINT NOT NULL,
    "PersonId"                  BIGINT NOT NULL,
    "AttendanceDate"            DATE NOT NULL,
    "CheckInTime"               TIMESTAMPTZ,
    "CheckOutTime"              TIMESTAMPTZ,
    "CheckInChannel"            VARCHAR(10),
    "CheckOutChannel"           VARCHAR(10),
    "CheckInFileStorageId"      BIGINT,
    "CheckOutFileStorageId"     BIGINT,
    "CheckInLatitude"           DECIMAL(9, 6),
    "CheckInLongitude"          DECIMAL(9, 6),
    "CheckInAccuracyMeters"     INT,
    "CheckOutLatitude"          DECIMAL(9, 6),
    "CheckOutLongitude"         DECIMAL(9, 6),
    "CheckOutAccuracyMeters"    INT,
    "Note"                      VARCHAR(500),
    "StatusId"                  INT NOT NULL DEFAULT 1,
    "RowVersion"                BYTEA NOT NULL DEFAULT '\x0000000000000000',
    "CreatedById"               BIGINT NOT NULL,
    "CreatedTime"               TIMESTAMPTZ NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    "UpdatedById"               BIGINT,
    "UpdatedTime"               TIMESTAMPTZ,
    "DeletedById"               BIGINT,
    "DeletedTime"               TIMESTAMPTZ,
    CONSTRAINT "UQ_Attendance_AttendanceGuid" UNIQUE ("AttendanceGuid")
);

CREATE UNIQUE INDEX "UQ_Attendance_PersonDate_Active"
    ON app."Attendance" ("PersonId", "AttendanceDate")
    WHERE ("DeletedTime" IS NULL AND "StatusId" > 0);

CREATE INDEX "IX_Attendance_CompanyId"
    ON app."Attendance" ("CompanyId");

CREATE INDEX "IX_Attendance_CompanyOfficeId"
    ON app."Attendance" ("CompanyOfficeId");

CREATE INDEX "IX_Attendance_CheckInFileStorageId"
    ON app."Attendance" ("CheckInFileStorageId");

CREATE INDEX "IX_Attendance_CheckOutFileStorageId"
    ON app."Attendance" ("CheckOutFileStorageId");

CREATE INDEX "IX_Attendance_AttendanceDate_Active"
    ON app."Attendance" ("AttendanceDate")
    INCLUDE ("AttendanceGuid", "PersonId", "CompanyId", "CompanyOfficeId")
    WHERE ("DeletedTime" IS NULL AND "StatusId" > 0);
